using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using MYOB.Data;using MYOB.Models;using MYOB.Services;using MYOB.Support;
namespace MYOB.Pages.Settings.PaymentMethods;public class CreateModel(ApplicationDbContext db,IPermissionService permissions):PageModel{[BindProperty]public PaymentMethod Item{get;set;}=new();public async Task<IActionResult> OnGetAsync()=>await permissions.HasAsync(User,ScreenCatalog.PaymentMethods,PermissionAction.Add)?Page():Forbid();public async Task<IActionResult> OnPostAsync(){if(!await permissions.HasAsync(User,ScreenCatalog.PaymentMethods,PermissionAction.Add))return Forbid();if(!ModelState.IsValid)return Page();db.PaymentMethods.Add(Item);await db.SaveChangesAsync();TempData["Message"]="تمت إضافة طريقة الدفع";return RedirectToPage("Index");}}
